    text(ctx, `COMBO x${(1 + 0.25 * Math.min(state.combo, 4)).toFixed(2)}`, 1038, 34, 14, '#fff', 'center');
  }
  // Reputation hearts.
  for (let i = 0; i < 5; i++) {
